xlcost_3579.java_algorithm:
function LCM(arr, n):
    max_num = max(arr)
    res = 1
    x = 1
    while x <= max_num:
        indexes = []
        for j from 0 to n-1:
            if arr[j] % x == 0:
                indexes.append(j)
        if length(indexes) >= 2:
            for j from 0 to length(indexes)-1:
                arr[indexes[j]] = arr[indexes[j]] / x
            res = res * x
        else:
            x = x + 1
    for i from 0 to n-1:
        res = res * arr[i]
    return res

